const row = $input.first().json || {};
let recs = row.recipes; if (typeof recs === 'string') { try { recs = JSON.parse(recs); } catch (e) { recs = []; } }
recs = recs || [];
if (!recs.length) return [{ json: { response: 'В библиотеке клиента подходящих рецептов НЕТ. Придумай новый рецепт, проверь ингредиенты через check_recipe_allergens и сохрани через save_recipe.' } }];
const list = recs.map(r => '#' + r.id + ' «' + r.title + '»' + (r.status === 'favorite' ? ' ★' : '') + ' — ' + (r.kcal != null ? r.kcal + ' ккал/порц' : 'БЖУ не задано') + (r.prep ? ', ' + r.prep + ' мин' : '')).join('\n');
return [{ json: { response: 'Нашёл в библиотеке клиента (' + recs.length + '): \n' + list + '\nЕсли подходит — проверь ингредиенты через check_recipe_allergens и предложи, не генерируй заново.' } }];
